text:
Load the library
&lt;link href="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@69.6.1/inst/htmlwidgets/lib/canvasXpress/canvasXpress.css" rel="stylesheet"&gt;
&lt;script src="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@69.6.1/inst/htmlwidgets/lib/canvasXpress/canvasXpress.min.js"&gt;&lt;/script&gt;

The markup and the spec
Genes are the variables (rows), samples the columns; the matrix goes in as data, and the sample annotation becomes a track over the columns. samplesClustered / variablesClustered turn on hierarchical clustering with dendrograms.
&lt;canvas id="heatmap" width="650" height="550"&gt;&lt;/canvas&gt;
&lt;script&gt;
  // standard normal via Box–Muller
  function gauss() {
    var u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  var ng = 40, ns = 30, genes = [], samps = [], cond = [], matrix = [];
  for (var j = 0; j &lt; ns; j++) { samps.push("S" + (j + 1)); cond.push(j &lt; ns / 2 ? "Tumor" : "Normal"); }
  for (var i = 0; i &lt; ng; i++) {
    genes.push("Gene" + (i + 1));
    var row = [];
    for (var k = 0; k &lt; ns; k++) {
      var val = gauss();
      if (i &lt; 20 && cond[k] === "Tumor")   val += 2;        // first block up in Tumor
      if (i &gt;= 20 && cond[k] === "Normal") val += 2;        // second block up in Normal
      row.push(Math.round(val * 1000) / 1000);
    }
    matrix.push(row);
  }

  var data = {
    y: { vars: genes, smps: samps, data: matrix },
    x: { Condition: cond }
  };

  var config = {
    graphType: "Heatmap",
    samplesClustered: true, variablesClustered: true,
    colorSpectrum: ["navy", "white", "firebrick3"],
    showSmpDendrogram: true, showVarDendrogram: true,
    title: "Clustered expression heatmap"
  };

  new CanvasXpress("heatmap", data, config);
&lt;/script&gt;

Load the library and the data
The 96-sample QC table is published next to this post as a small JS object, qc-data.js — QC_DATA is a sample-centric CanvasXpress data object (each sample is a point; z holds its lane/batch/library).
&lt;link href="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@73.3.0/inst/htmlwidgets/lib/canvasXpress/canvasXpress.css" rel="stylesheet"&gt;
&lt;script src="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@73.3.0/inst/htmlwidgets/lib/canvasXpress/canvasXpress.min.js"&gt;&lt;/script&gt;
&lt;script src="qc-data.js"&gt;&lt;/script&gt;

The panels
The overview heatmap transposes the data to metrics × samples and z-scores each metric. The four triage panels read QC_DATA directly and all share broadcastGroup: "qc" — select points in one and the same samples re-mark in the rest.
&lt;canvas id="qcHeat" width="820" height="420"&gt;&lt;/canvas&gt;
&lt;canvas id="qcMap" width="640" height="360"&gt;&lt;/canvas&gt;
&lt;canvas id="qcContam" width="640" height="360"&gt;&lt;/canvas&gt;
&lt;canvas id="qcQ30" width="640" height="360"&gt;&lt;/canvas&gt;
&lt;canvas id="qcReads" width="820" height="300"&gt;&lt;/canvas&gt;
&lt;script&gt;
  var metrics = QC_DATA.y.smps, samples = QC_DATA.y.vars, rows = QC_DATA.y.data;

  // Overview: transpose to metrics x samples and z-score each metric.
  var hmData = metrics.map(function (_, c) {
    var col = rows.map(function (r) { return r[c]; });
    var mean = col.reduce(function (a, b) { return a + b; }, 0) / col.length;
    var sd = Math.sqrt(col.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / col.length) || 1;
    return col.map(function (v) { return Math.round((v - mean) / sd * 100) / 100; });
  });
  new CanvasXpress("qcHeat",
    { y: { vars: metrics, smps: samples, data: hmData },
      x: { Batch: QC_DATA.z.Batch, Library: QC_DATA.z.Library } },
    { graphType: "Heatmap", samplesClustered: true, variablesClustered: true,
      colorSpectrum: ["navy", "white", "firebrick3"],
      title: "QC metrics (z-scored) — 96 samples clustered" });

  // Linked triage panels (same QC_DATA, shared broadcast group).
  function panel(id, cfg) {
    new CanvasXpress(id, QC_DATA, Object.assign({ broadcast: true, broadcastGroup: "qc" }, cfg));
  }
  panel("qcMap", { graphType: "Scatter2D", xAxis: ["pct_duplication"], yAxis: ["pct_mapped"],
    colorBy: "Batch", sizeBy: "total_reads", title: "Mapping rate vs duplication — select bottom-right" });
  panel("qcContam", { graphType: "Scatter2D", xAxis: ["pct_mapped"], yAxis: ["contamination_freemix"],
    colorBy: "Batch", title: "Contamination (freemix) vs mapping rate" });
  panel("qcQ30", { graphType: "Scatter2D", xAxis: ["gc_content"], yAxis: ["pct_q30"],
    colorBy: "Library", title: "Q30 vs GC content, coloured by library" });
  panel("qcReads", { graphType: "Bar", graphOrientation: "vertical", xAxis: ["total_reads"],
    colorBy: "Batch", title: "Total reads per sample (flag the short ones)" });
&lt;/script&gt;

Load the library
Drop one script tag (and the stylesheet) on your page. Here we pin to a released version on a CDN:
&lt;link href="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@69.6.1/inst/htmlwidgets/lib/canvasXpress/canvasXpress.css" rel="stylesheet"&gt;
&lt;script src="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@69.6.1/inst/htmlwidgets/lib/canvasXpress/canvasXpress.min.js"&gt;&lt;/script&gt;

The markup and the spec
Give the page a canvas, then build the data (a value matrix plus annotations) and a config, and call new CanvasXpress(...):
&lt;canvas id="volcano" width="650" height="500"&gt;&lt;/canvas&gt;
&lt;script&gt;
  // Normal-distribution helpers (no stats library needed in the browser)
  function gauss() {                        // standard normal via Box–Muller
    var u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }
  function normCdf(x) {                      // standard normal CDF via an erf approximation
    var s = x &lt; 0 ? -1 : 1, ax = Math.abs(x) / Math.SQRT2;
    var t = 1 / (1 + 0.3275911 * ax);
    var y = 1 - (((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t) * Math.exp(-ax * ax);
    return 0.5 * (1 + s * y);
  }

  // Simulate a realistic volcano: most genes unchanged, a minority differentially
  // expressed; significance follows effect size / standard error. Genes are the
  // variables (rows); each row holds [logFC, -log-pVal].
  var genes = [], rows = [], group = [], fc = [];
  for (var i = 0; i &lt; 1000; i++) {
    var de = Math.random() &lt; 0.12;                          // ~12% truly changed
    var sgn = Math.random() &lt; 0.5 ? -1 : 1;
    var effect = de ? sgn * (0.8 + 0.9 * Math.random()) : 0;
    var se = 0.22 + 0.5 * Math.random();                    // per-gene standard error
    var f = effect + se * gauss();                          // observed log2FC
    var praw = 2 * (1 - normCdf(Math.abs(f / se)));         // z-test p-value
    var p = Math.min(-Math.log(Math.max(praw, 1e-16)) / Math.LN10, 16);
    genes.push("Gene" + (i + 1));
    rows.push([Math.round(f * 1000) / 1000, Math.round(p * 1000) / 1000]);
    group.push(f &gt; 1 && p &gt; 1.3 ? "Increased" : f &lt; -1 && p &gt; 1.3 ? "Decreased" : "NoChange");
    fc.push(Math.round(Math.pow(2, Math.abs(f)) * 100) / 100);
  }

  var data = {
    y: { vars: genes, smps: ["logFC", "-log-pVal"], data: rows },
    z: { Group: group, FC: fc }
  };

  var config = {
    graphType: "Scatter2D",
    title: "Publication-ready volcano plot",
    xAxis: ["logFC"], yAxis: ["-log-pVal"],
    xAxisTitle: "log2 fold change", yAxisTitle: "-log10 p-value",
    colorBy: "Group",
    colorKey: { Group: { Increased: "rgba(197,27,38,0.75)",
                         Decreased: "rgba(33,102,172,0.75)",
                         NoChange:  "rgba(150,150,150,0.35)" } },
    sizeBy: "FC", sizes: [3, 6, 9, 12, 15],
    showDecorations: true,
    decorations: { line: [
      { color: "rgba(120,120,120,0.8)", width: 1, x: 1 },
      { color: "rgba(120,120,120,0.8)", width: 1, x: -1 },
      { color: "rgba(120,120,120,0.8)", width: 1, y: 1.301 }
    ] }
  };

  new CanvasXpress("volcano", data, config);
&lt;/script&gt;

Load the library
&lt;link href="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@73.3.0/inst/htmlwidgets/lib/canvasXpress/canvasXpress.css" rel="stylesheet"&gt;
&lt;script src="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@73.3.0/inst/htmlwidgets/lib/canvasXpress/canvasXpress.min.js"&gt;&lt;/script&gt;

The markup and the spec
Four tracks that share one coordinate axis: gene models (box, multi-exon, connected), coverage across three tissues (bar), an expression heatmap (heatmap), and variant markers (triangle).
&lt;canvas id="genome" width="760" height="520"&gt;&lt;/canvas&gt;
&lt;script&gt;
  // Gene models: each gene is a set of exon [start, end] intervals, drawn connected.
  var genes = [];
  for (var j = 0; j &lt; 4; j++) {
    var start = 40 + j * 120, nex = 2 + Math.floor(Math.random() * 3), exons = [];
    for (var k = 0; k &lt; nex; k++) exons.push([start + k * 30, start + k * 30 + 18]);
    genes.push({ id: "GENE" + (j + 1), dir: j % 2 === 0 ? "right" : "left",
                 fill: "rgb(70,130,220)", outline: "rgb(0,0,0)", data: exons });
  }

  // Coverage and expression: one entry per binned position, three tissues each.
  var coverage = [], express = [], rnd = function (a, b) { return a + Math.floor(Math.random() * (b - a + 1)); };
  for (var i = 0; i &lt; 22; i++) {
    var o = 50 + i * 22;
    coverage.push({ id: "p" + i, offset: o, data: [rnd(8, 45), rnd(8, 45), rnd(8, 45)] });
    express.push({ id: "p" + i, offset: o,
                   data: [Math.round(Math.random() * 4 - 2), Math.round(Math.random() * 4 - 2),
                          Math.round(Math.random() * 4 - 2)] });
  }

  // Variants: point markers at genomic positions.
  var snps = [];
  for (var s = 0; s &lt; 9; s++)
    snps.push({ id: "rs" + (1000 + s), offset: rnd(45, 520), fill: "rgb(200,40,40)", outline: "rgb(0,0,0)" });

  var data = { tracks: [
    { name: "Genes (exon models)", type: "box", connect: true, data: genes },
    { name: "Coverage — Heart / Liver / Kidney", type: "bar", height: 120,
      fill: "rgb(80,80,200)", outline: "rgb(60,60,60)", data: coverage },
    { name: "Expression (z-score)", type: "heatmap", height: 90, data: express },
    { name: "SNPs", type: "triangle", data: snps }
  ]};

  var config = { graphType: "Genome", background: "rgb(245,245,245)", featureStaggered: true,
                 title: "Multi-track genome browser: genes, coverage, expression and variants" };

  new CanvasXpress("genome", data, config);
&lt;/script&gt;

Load the library
&lt;link href="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@69.6.1/inst/htmlwidgets/lib/canvasXpress/canvasXpress.css" rel="stylesheet"&gt;
&lt;script src="https://cdn.jsdelivr.net/gh/neuhausi/canvasXpress@69.6.1/inst/htmlwidgets/lib/canvasXpress/canvasXpress.min.js"&gt;&lt;/script&gt;

The markup and the spec
Subjects are the variables (rows); each row holds [Time, Time-Censor] (1 = censored, 0 = event). The arm rides along as a variable annotation. The key is graphType: "KaplanMeier" and passing both columns to xAxis.
&lt;canvas id="km" width="650" height="500"&gt;&lt;/canvas&gt;
&lt;script&gt;
  var subj = [], rows = [], arm = [];
  for (var i = 0; i &lt; 200; i++) {
    var a = Math.random() &lt; 0.5 ? "Treatment" : "Control";
    var base = a === "Treatment" ? 60 : 40;                 // treatment survives longer
    var time = Math.round(-base * Math.log(Math.random()) * 10) / 10;  // exponential
    var cens = Math.random() &lt; 0.3 ? 1 : 0;                 // 1 = censored, 0 = event
    subj.push("Subj" + (i + 1));
    rows.push([time, cens]);
    arm.push(a);
  }

  var data = {
    y: { vars: subj, smps: ["Time", "Time-Censor"], data: rows },
    z: { Arm: arm }
  };

  var config = {
    graphType: "KaplanMeier",
    xAxis: ["Time", "Time-Censor"],
    colorBy: "Arm",
    title: "Overall survival by treatment arm",
    xAxisTitle: "Time (weeks)", yAxisTitle: "Probability of survival",
    invertCensored: true,                 // draw censoring ticks
    showKMConfidenceIntervals: false
  };

  new CanvasXpress("km", data, config);
&lt;/script&gt;

A full violin per group

cx = CanvasXpress(render_to="violin", data=data, config={
